// Plotagem rápida de pixel no Linear Framebuffer (32-bpp)
static inline void put_pixel(Framebuffer* fb, uint32_t x, uint32_t y, uint32_t color) {
    if (x >= fb->width || y >= fb->height) return;
    uint32_t* pixel_addr = (uint32_t*)((uint8_t*)fb->base + y * fb->pitch + x * 4);
    *pixel_addr = color;
}
